        'ta' => 'தொழிலாளர் தரநிலைகளை ஏற்று அங்கீகரித்தல் மற்றும் நடைமுறைப்படுத்துதல் தொடர்பாக சர்வதேச தொழிலாளர் அமைப்பிற்கு அனுப்பும் பதில்கள் குறித்த விடயங்களைப் பரிசீலித்தல்'
